UIDustEmitter=function(game){Phaser.Particles.Arcade.Emitter.call(this,game,0,0,40);this.particleClass=UIDustParticle;this.makeParticles('game',['dust0','dust1','dust2']);this.minParticleSpeed.setTo(-95,-95);this.maxParticleSpeed.setTo(95,95);this.particleDrag.setTo(50,50);this.setAlpha(0.8,1.0);this.setRotation(0,0);this.minParticleScale=UIConstants.GAME_ASSET_SCALE*0.8;this.maxParticleScale=UIConstants.GAME_ASSET_SCALE*1.0;this.gravity=0;this.kill();this.visible=false;};UIDustEmitter.prototype=Object.create(Phaser.Particles.Arcade.Emitter.prototype);UIDustEmitter.prototype.constructor=UIDustEmitter;UIDustEmitter.prototype.preUpdate=function(){if(!this.exists||this.game.physics.arcade.isPaused){return false;}return Phaser.Particles.Arcade.Emitter.prototype.preUpdate.call(this);};UIDustEmitter.prototype.update=function(){if(!this.exists||this.game.physics.arcade.isPaused){return;}Phaser.Particles.Arcade.Emitter.prototype.update.call(this);if(this.countLiving()==0){this.kill();this.visible=false;}};UIDustEmitter.prototype.postUpdate=function(){if(!this.exists){return;}Phaser.Particles.Arcade.Emitter.prototype.postUpdate.call(this);};UIDustEmitter.prototype.spawn=function(x,y){this.revive();this.visible=true;this.x=x;this.y=y;this.explode(2000,QualityManager.getQualityValue(QualityManager.QUALITY_PARAMETERS.CRATE_LAND_DUST_COUNT));};UIDustEmitter.prototype.retire=function(){this.kill();this.visible=false;this.callAll('retire');};